/** Interrupt Number Definitions */
#define NUMBER_OF_INT_VECTORS 32                 /**< Number of interrupts in the Vector table */

typedef enum IRQn {
  /* Auxiliary constants */
  NotAvail_IRQn                = -128,             /**< Not available device specific interrupt */

  /* Core interrupts */
  NonMaskableInt_IRQn          = 0,                /**< SysIRQ, Non Maskable Interrupt */
  Software_IRQn                = 1,                /**< Software triggered Interrupt */
  RtosTimer0_IRQn              = 2,                /**< Internal RTOS Timer0 Interrupt */
  RtosTimer1_IRQn              = 3,                /**< Internal RTOS Timer1 Interrupt */
  Profiling_IRQn               = 4,                /**< Profiling Interrupt */

  /* Device specific interrupts */
  DMA2_0_IRQn                  = 6,                /**< DMA2 Channel 0 Error or Transfer Complete */
  DMA2_1_IRQn                  = 7,                /**< DMA2 Channel 1 Error or Transfer Complete */
  DMA2_2_IRQn                  = 8,                /**< DMA2 Channel 2 Error or Transfer Complete */
  DMA2_3_IRQn                  = 9,                /**< DMA2 Channel 3 Error or Transfer Complete */
  DMA2_4_IRQn                  = 10,               /**< DMA2 Channel 4 Error or Transfer Complete */
  DMA2_5_IRQn                  = 11,               /**< DMA2 Channel 5 Error or Transfer Complete */
  DMA2_6_IRQn                  = 12,               /**< DMA2 Channel 6 Error or Transfer Complete */
  DMA2_7_IRQn                  = 13,               /**< DMA2 Channel 7 Error or Transfer Complete */
  MU2_B_IRQn                   = 14,               /**< Messaging Unit 2 - Side B (to communicate with M33) */
  MU3_B_IRQn                   = 15,               /**< Messaging Unit 3 - Side B (to communicate with M33) */
  WDOG5_IRQn                   = 16,               /**< Watchdog 5 Interrupt */
  TPM8_IRQn                    = 17,               /**< Timer PWM module 8 */
  SAI0_IRQn                    = 18,               /**< Serial Audio Interface 0 */
  SAI1_IRQn                    = 19,               /**< Serial Audio Interface 1 */
  SAI4_IRQn                    = 22,               /**< Serial Audio Interface 4 */
  SAI5_IRQn                    = 23,               /**< Serial Audio Interface 5 */
  SAI6_IRQn                    = 24,               /**< Serial Audio Interface 6 */
  SAI7_IRQn                    = 25,               /**< Serial Audio Interface 7 */
  SPDIF_IRQn                   = 26,               /**< Sony/Phillips Digital Interface */
  GPIOA_IRQn                   = 27,               /**< General Purpose Input/Output A interrupt */
  GPIOB_IRQn                   = 28,               /**< General Purpose Input/Output B interrupt */
  GPIOD_IRQn                   = 29,               /**< General Purpose Input/Output D interrupt */
  GPIOE_IRQn                   = 30,               /**< General Purpose Input/Output E interrupt */
  GPIOF_IRQn                   = 31                /**< General Purpose Input/Output F interrupt */
} IRQn_Type;

