#define AHB_ADDR_REMAP_CR_RADDR_MASK             (0xFFFFF80U)
#define AHB_ADDR_REMAP_CR_RADDR_SHIFT            (7U)
/*! RADDR - Remap address. */
#define AHB_ADDR_REMAP_CR_RADDR(x)               (((uint32_t)(((uint32_t)(x)) << AHB_ADDR_REMAP_CR_RADDR_SHIFT)) & AHB_ADDR_REMAP_CR_RADDR_MASK)
/*! @} */

